def handle(args, state, ds):
    st = ds.sync_status()
    if st['drift'] is False:
        return {'status': 'in_sync', 'detail': st['detail'], 'message': 'Directory view matches the source of truth. Sync is up to date; no further reconciliation needed.'}
    return {'status': 'drift_detected', 'detail': st['detail'], 'message': 'Directory drift detected (' + st['detail'] + '). Call sync_directory_view again to apply the next reconciliation step.'}

def handle(args, state, ds):
    status = ds.sync_status()
    drift = status['drift']
    detail = status['detail']
    if drift is False:
        return {'status': 'in_sync', 'drift': drift, 'detail': detail, 'message': 'Directory sync verified: the directory view matches the source of truth. No further sync checks needed.'}
    return {'status': 'drift_detected', 'drift': drift, 'detail': detail, 'message': 'Directory sync IN PROGRESS: drift detected (' + detail + '). Run directory_sync_status again to re-check the sync state.'}
